// 앞 단계 응답에서 오늘 비 소식 만들기. 코드를 바꾸면 위 HTTP 주소의 코드도 같이 바꾸세요.
const code = "1111051500";
const d = $input.first().json.data[code].data;
const today = d.timelines.hourly[0].time.slice(0, 10);

const hours = d.timelines.hourly.filter((s) => s.time.startsWith(today));
const rainy = hours.filter((s) =>
  (s.values.precipitation ?? 0) > 0 || (s.values.precipitationProbability ?? 0) >= 60);

// daily 는 오후가 되면 오늘 칸이 빠질 수 있어, 오늘 최고는 시간별 값에서 구합니다
const max = Math.max(...hours.map((s) => s.values.temperature ?? -99));
const text = rainy.length
  ? `☔ 오늘 ${rainy[0].time.slice(11, 16)}부터 비 소식이 있습니다. 우산 챙기세요.`
  : `오늘은 비 소식이 없습니다. 남은 시간 최고 ${max}℃`;

return [{ json: { text, rain: rainy.length > 0 } }];
